// Vendors the chat UI contract from a happy-agent checkout into
// Tests/HappyCoreTests/Fixtures/chat-ui: `ui.schema.json` (the catalog and
// wire schemas) and `actions.fixtures.json` (the conformance vectors, with
// the `mediaLayout` table HappyLayoutTests reads), both generated by
// @slopus/happy-agent-client and copied byte for byte from one commit.
// `vendored.json` records that commit and each file's SHA-256;
// ChatUiContractTests fails when the files and the record disagree, so
// neither is edited by hand.
//
//   node scripts/vendor-chat-ui.mjs <happy-agent checkout> <commit>

import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const [checkout, commit] = process.argv.slice(2);
if (!checkout || !commit) throw new Error("usage: vendor-chat-ui.mjs <happy-agent checkout> <commit>");

const source = "packages/happy-agent-client/fixtures/ui";
const files = ["ui.schema.json", "actions.fixtures.json"];
const target = resolve(dirname(fileURLToPath(import.meta.url)), "../Tests/HappyCoreTests/Fixtures/chat-ui");
const git = (...args) => execFileSync("git", ["-C", checkout, ...args], { maxBuffer: 64 * 1024 * 1024 });

const sha = git("rev-parse", `${commit}^{commit}`).toString().trim();
mkdirSync(target, { recursive: true });
const sha256 = {};
for (const file of files) {
    const bytes = git("show", `${sha}:${source}/${file}`);
    writeFileSync(resolve(target, file), bytes);
    sha256[file] = createHash("sha256").update(bytes).digest("hex");
}
writeFileSync(resolve(target, "vendored.json"), `${JSON.stringify({ repository: "happy-agent", path: source, commit: sha, sha256 }, null, 4)}\n`);
console.log(`chat UI contract vendored from happy-agent ${sha}`);
